#include <bits/stdc++.h>
#define MAXN 150
using namespace std;
typedef long long ll;
typedef pair<int,int> pii;

struct Edge {
    int to, rev;
    ll cap;
    Edge(int t, int r, ll c) : to(t), rev(r), cap(c) {}
};

struct Dinic {
    int N, S, T;
    vector<vector<Edge>> adj;
    vector<int> level, ptr;
    Dinic(int n, int s, int t) : N(n), S(s), T(t) { adj.resize(n); level.resize(n); ptr.resize(n); }
    void addEdge(int u, int v, ll c) {
        adj[u].emplace_back(v, (int)adj[v].size(), c);
        adj[v].emplace_back(u, (int)adj[u].size()-1, 0);
    }
    bool bfs() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[S] = 0; q.push(S);
        while(!q.empty()) {
            int u = q.front(); q.pop();
            for(auto &e : adj[u]) if(e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
        return level[T] != -1;
    }
    ll dfs(int u, ll f) {
        if(u == T) return f;
        for(int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
            Edge &e = adj[u][i];
            if(e.cap > 0 && level[e.to] == level[u] + 1) {
                ll ret = dfs(e.to, min(f, e.cap));
                if(ret) {
                    e.cap -= ret;
                    adj[e.to][e.rev].cap += ret;
                    return ret;
                }
            }
        }
        return 0;
    }
    ll maxflow() {
        ll ans = 0;
        while(bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while(ll f = dfs(S, 1e18)) ans += f;
        }
        return ans;
    }
};

int pos[MAXN][MAXN], tMat[MAXN][MAXN], aMat[MAXN][MAXN];

void computeT(int i, int j, vector<string>& sc, int n, int cur) {
    if(i<0||i>=n||j<0||j>=n) return;
    if(!isdigit(sc[i][j]) && sc[i][j]!='Z') return;
    if(tMat[i][j]!=-1 && tMat[i][j]<=cur) return;
    tMat[i][j] = (tMat[i][j]==-1)?cur:min(tMat[i][j],cur);
    computeT(i+1,j,sc,n,cur+1);
    computeT(i-1,j,sc,n,cur+1);
    computeT(i,j+1,sc,n,cur+1);
    computeT(i,j-1,sc,n,cur+1);
}

void computeA(int i, int j, vector<string>& sc, int n, int cur) {
    if(i<0||i>=n||j<0||j>=n) return;
    if(!isdigit(sc[i][j])) return;
    if(aMat[i][j]!=-1 && aMat[i][j]<=cur) return;
    aMat[i][j] = (aMat[i][j]==-1)?cur:min(aMat[i][j],cur);
    computeA(i+1,j,sc,n,cur+1);
    computeA(i-1,j,sc,n,cur+1);
    computeA(i,j+1,sc,n,cur+1);
    computeA(i,j-1,sc,n,cur+1);
}

int main() {
    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    int n, t;
    cin >> n >> t;
    int n2 = n*n;
    int total = n2*2 + 2;
    Dinic din(total, 0, total-1);
    vector<string> sc(n), caps(n);
    int cnt = 1;
    for(int i=0;i<n;i++) for(int j=0;j<n;j++) pos[i][j] = cnt++;
    int zi=0,zj=0;
    for(int i=0;i<n;i++) {
        cin >> sc[i];
        for(int j=0;j<n;j++) if(sc[i][j]=='Z') { zi=i; zj=j; }
    }
    for(int i=0;i<n;i++) cin >> caps[i];
    memset(tMat, -1, sizeof(tMat));
    computeT(zi,zj,sc,n,0);
    for(int i=0;i<n;i++) for(int j=0;j<n;j++) if(tMat[i][j]==-1 && isdigit(sc[i][j])) tMat[i][j] = t;
    for(int i=0;i<n;i++) for(int j=0;j<n;j++) {
        if(isdigit(sc[i][j])) {
            int lim = sc[i][j]-'0';
            din.addEdge(0, pos[i][j], lim);
            memset(aMat, -1, sizeof(aMat));
            computeA(i,j,sc,n,0);
            for(int k=0;k<n;k++) for(int l=0;l<n;l++) {
                if(aMat[k][l]!=-1 && tMat[k][l]!=-1 && aMat[k][l]<=tMat[k][l] && aMat[k][l]<=t) {
                    bool ok = true;
                    if(aMat[k][l]==tMat[k][l]) {
                        ok = false;
                        if(k+1<n && aMat[k+1][l]!=-1 && aMat[k+1][l]<tMat[k+1][l]) ok=true;
                        if(k-1>=0 && aMat[k-1][l]!=-1 && aMat[k-1][l]<tMat[k-1][l]) ok=true;
                        if(l+1<n && aMat[k][l+1]!=-1 && aMat[k][l+1]<tMat[k][l+1]) ok=true;
                        if(l-1>=0 && aMat[k][l-1]!=-1 && aMat[k][l-1]<tMat[k][l-1]) ok=true;
                    }
                    if(ok) din.addEdge(pos[i][j], n2+pos[k][l], lim);
                }
            }
        }
    }
    for(int i=0;i<n;i++) for(int j=0;j<n;j++) if(isdigit(caps[i][j])) din.addEdge(n2+pos[i][j], total-1, caps[i][j]-'0');
    cout << din.maxflow() << '\n';
    return 0;
}
